+  let exitOnDegraded = DEFAULT_EXIT_ON_DEGRADED;
+  if (view.exit !== null && view.exit !== undefined) {
+    if (typeof view.exit === "number" && Number.isInteger(view.exit) && view.exit >= 0 && view.exit <= 125) {
